-- P10 content seeds: the gathering catalogue — 42 material/gem/proc/fish
-- items and 21 resource-node definitions (5 tiers × 4 professions, plus
-- Dawnpetal), authored THROUGH the Dawned-Admin Professions editor (A1-e) and
-- published via its rail; these rows are that output, frozen for deploys.
-- ON CONFLICT DO NOTHING: a panel-retuned live row must never be reverted by a
-- redeploy. (Doctrine: seed files are append-only history — repairs ship as NEW
-- migrations, never edits.)
--
-- Two rows here are REPAIRS to P8 content rather than new rows, and a fresh
-- database gets them from 0012 first, so the ON CONFLICT keeps the old value
-- and the UPDATE below fixes it: `item_material_dawnpetal` was authored at
-- ilvl 4 before the professions ladder existed and is the Elder Grove's T5
-- rare per PROFESSIONS.md §4, and `loot_dawnshore_spore` dropped it off a
-- level-3 mob. Meadowbell — the herb that shore actually grows — takes its
-- slot in the table.
--
-- PLACEMENTS are deliberately NOT here. Where a birch stands lives in the map
-- bake (`placements.json`), which deploy/BACKUP.sh archives and a map publish
-- rewrites; duplicating it into SQL would give the world two sources of truth
-- about the same forest. Re-plant with Dawned-Admin's tools/content/author-nodes.mjs.
-- content_items: 42 published rows

-- content_resource_nodes: 21 published rows

-- P8 repairs (see the header): applied with UPDATE because 0012 seeds these
-- ids first and the INSERTs above would be swallowed by ON CONFLICT.
UPDATE "content_items" SET "def" = '{"id":"item_material_dawnpetal","icon":"delapouite/herbs-bundle","ilvl":27,"name":"Dawnpetal","slot":"none","bound":false,"stack":50,"stats":{},"value":34,"effect":null,"flavor":"Opens at first light and closes on anyone who is late.","rarity":"rare","weapon":null,"category":"material","modelRef":null,"classLock":[],"armorClass":null,"consumable":null,"requiresLevel":1}'::jsonb WHERE "id" = 'item_material_dawnpetal' AND "status" = 'published' AND ("def"->>'ilvl')::int < 20;
UPDATE "content_loot_tables" SET "def" = '{"id":"loot_dawnshore_spore","name":"Dawnshore Spore-dwellers","entries":[{"kind":"nothing","weight":42},{"ref":"item_junk_spore_sac","kind":"item","maxQty":2,"minQty":1,"weight":16},{"ref":"item_junk_chipped_tusk","kind":"item","maxQty":1,"minQty":1,"weight":8},{"ref":"item_material_meadowbell","kind":"item","maxQty":1,"minQty":1,"weight":8},{"ref":"item_consumable_tonic_minor","kind":"item","maxQty":1,"minQty":1,"weight":6},{"ref":"item_consumable_antidote","kind":"item","maxQty":1,"minQty":1,"weight":4},{"kind":"gold","maxQty":9,"minQty":3,"weight":8},{"ref":"loot_dawnshore_gear","kind":"table","weight":12},{"ref":"loot_weald_gear","kind":"table","weight":4,"minKillerLevel":7}]}'::jsonb WHERE "id" = 'loot_dawnshore_spore' AND "status" = 'published' AND "def"::text LIKE '%item_material_dawnpetal%';
